def count_colors(N):
    board = {}
    count_B = 0
    count_W = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            # Standard checkerboard coloring: (i+j) even is one color (Black, since corners (1,1) have sum 2)
            color = 'B' if (i + j) % 2 == 0 else 'W'
            board[(i, j)] = color
            if color == 'B':
                count_B += 1
            else:
                count_W += 1
    return count_B, count_W

N = 5
count_B, count_W = count_colors(N)
print(f"5x5 Board: Black count = {count_B}, White count = {count_W}")
